head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.edu_appl_seq = "";
// 화면 리사이징

scwin.gDepCd = js_dep_cd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        await scwin.setCode();
        $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF16515.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF16515.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_MASTER_OnFail
 * @description MASTER On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_MASTER_OnFail = async function() {
    try {
        await $c.win.alert(dts_MASTER);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF16515.dts_MASTER_OnFail" });
    }
};

/**
 * @method
 * @name dts_MASTER_OnLoadError
 * @description dts_MASTER 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_MASTER_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_MASTER);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF16515.dts_MASTER_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_MASTER_OnLoadCompleted
 * @description dts_MASTER 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_MASTER_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        if (rowcount <= 0) {
            dts_MASTER.removeAll();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF16515.dts_MASTER_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_Grid_OnClick
 * @description grd_Grid 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_Grid_OnClick = function(row, colid) {

};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        scwin.edu_appl_seq = dts_MASTER.getCellData(row, "EDU_APPL_SEQ");
        if (colid === 'APPL_DD') {
            const options = {
                id: "ULDSTF16516",
                title: "상세보기",
                type: "browserPopup",
                width: "100px",
                height: "100px",
                callbackFn: "scwin.popupCallback"
            };

            $c.win.openPopup("/support/ULDSTF16516.gfm", options);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF16515.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onblur
 * @description txb_isur_cd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_isur_cd.getValue() === "") {
            txb_com_abbrv.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF16515.txb_isur_cd_onblur" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onfocus
 * @description txb_isur_cd 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF16515.txb_isur_cd_onfocus" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onkeyup
 * @description txb_isur_cd 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onkeyup = function() {
    try {
        if (txb_isur_cd.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF16515.txb_isur_cd_onkeyup" });
    }
};

/**
 * @method
 * @name img_com_srch_onclick
 * @description img_com_srch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_com_srch_onclick = function() {
    try {
        $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF16515.img_com_srch_onclick" });
    }
};

/**
 * @method
 * @name cmb_DEP_CD_onselchange
 * @description cmb_DEP_CD onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_DEP_CD_onselchange = function() {
    try {
        scwin.gDepCd = cmb_DEP_CD.getValue(); // ;.ValueOfIndex("VALUE", cmb_DEP_CD.Index);

        dts_EMP_NO.UseFilter = true;
        dts_EMP_NO.Filter();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF16515.cmb_DEP_CD_onselchange" });
    }
};

/**
 * @method
 * @name dts_EMP_NO_OnFilter
 * @description EMP NO On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_EMP_NO_OnFilter = function(row) {
    try {
        if (scwin.gDepCd === "") {
            // 전체일 경우 모두 보여준다.
            return true;
        } else {
            if (dts_EMP_NO.getCellData(row, "dep_cd") === scwin.gDepCd ||
                dts_EMP_NO.getCellData(row, "dep_cd") === "") {
                return true;
            } else {
                return false;
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF16515.dts_EMP_NO_OnFilter" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF16515.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF16515.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF16515.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF16515.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF16515.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else {
            return true;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF16515.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF16515.xml", SCREN_PROCS_TP_CD_07, '');
        $c.data.downloadGridViewExcel(grd_Grid, {fileName: "공시교육참가현황", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF16515.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name btn_SDATE_onclick
 * @description btn_SDATE 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_SDATE_onclick = function() {
    try {
        popUpCalendar2(edt_SDATE); // 공시일자-종료일 이미지 버튼 클릭 시 달력 팝업
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF16515.btn_SDATE_onclick" });
    }
};

/**
 * @method
 * @name btn_EDATE_onclick
 * @description btn_EDATE 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_EDATE_onclick = function() {
    try {
        popUpCalendar2(edt_EDATE); // 공시일자-시작일 이미지 버튼 클릭 시 달력 팝업
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF16515.btn_EDATE_onclick" });
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = cmb_PeriodTp.getValue();
        if (vTp === '0') {
            edt_SDATE.setValue('');
            edt_EDATE.setValue('');
        } else {
            $c.stf.setFromToDate(vTp, edt_SDATE, edt_EDATE); // 기간선택 콤보박스

        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF16515.cmb_PeriodTp_onselchange" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    const sbmOptions = {
        id : "sbm_dts_EMP_NO",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_EMP_NO=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_dts_DEP_CD",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_DEP_CD=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    url += "&ISUR_CD=" + txb_isur_cd.getValue();
    url += "&EMP_NO=" + cmb_EMP_NO.getValue();
    url += "&DEP_CD=" + cmb_DEP_CD.getValue();
    url += "&EDU_STRT_DD=" + edt_SDATE.getValue();
    url += "&EDU_END_DD=" + edt_EDATE.getValue();
    url += "&SCREN_ID=" + "ULDSTF16515.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_MASTER",
        action : "/ListedCompany.do",
        ref : "",
        target : "dts_MASTER=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};
